// 圖片快取（首次用到先 decode）
const STN_FG_IMG = {};
function STN_FG_img(it) { let im = STN_FG_IMG[it.src.length + ':' + it.x + ':' + it.y]; if (!im) { im = new Image(); im.src = it.src; STN_FG_IMG[it.src.length + ':' + it.x + ':' + it.y] = im; } return im; }
// 預載：STN_FG_preload('bus') 或者唔傳參數全部預載
function STN_FG_preload(site) { for (const s in STN_FG) if (!site || s === site) STN_FG[s].forEach(p => p.forEach(STN_FG_img)); }
// 取某屏遮擋件（可傳 footY：只要 baseY > footY 嗰啲，即係會遮住腳底喺 footY 嘅角色）
function STN_FG_list(site, panelIndex, footY) { const P = (STN_FG[site] || [])[panelIndex] || []; return footY == null ? P : P.filter(it => it.baseY > footY); }
// 繪製：ox,oy = 該屏左上角喺畫布嘅位置；scale = 畫布像素 / 背景圖像素（例如 b.w / 768）；
// 可選 only = 單一件（配合深度排序逐件畫）
function STN_FG_draw(ctx, site, panelIndex, ox, oy, scale, only) {
  const P = only ? [only] : STN_FG_list(site, panelIndex);
  for (const it of P) { const im = STN_FG_img(it); if (!im.complete || !im.naturalWidth) continue;
    ctx.drawImage(im, ox + it.x * scale, oy + it.y * scale, it.w * scale, it.h * scale); }
}
if (typeof window !== 'undefined') Object.assign(window, { STN_FG, STN_FG_W, STN_FG_H, STN_FG_draw, STN_FG_list, STN_FG_preload });
